#!/usr/bin/env python3
"""Probe helpers: run the original (or mine) on a list of commands in a scratch dir."""
import json, os, subprocess, sys, tempfile, shutil

ORIG = '/workspace/executable'
MINE = '/workspace/.claude/worktrees/agent-a9f6582e28e51b822/target/release/bimcraft-cli'
W = '/tmp/members-agent/w'


def run(cmds, exe=ORIG, files=(), save=None, pre=None, cwd=None):
    """cmds: list of 'id {json}' strings (or (id, dict)). Returns (stdout, stderr, code)."""
    d = cwd or tempfile.mkdtemp(prefix='pr', dir='/tmp/members-agent')
    for f in files:
        shutil.copy(f, d)
    args = [exe, 'run']
    if pre:
        args.append(pre)
    for c in cmds:
        if isinstance(c, tuple):
            c = c[0] + ' ' + json.dumps(c[1])
        args += ['--cmd', c]
    if save:
        args += ['--save', save]
    p = subprocess.run(args, cwd=d, capture_output=True, timeout=120)
    out = (p.stdout.decode('utf-8', 'replace'), p.stderr.decode('utf-8', 'replace'), p.returncode)
    saved = None
    if save and os.path.exists(os.path.join(d, save)):
        saved = open(os.path.join(d, save)).read()
    if not cwd:
        shutil.rmtree(d)
    if save:
        return out + (saved,)
    return out


def last_err(cmds, **kw):
    o, e, c = run(cmds, **kw)[:3]
    return e.strip() if c else ('OK ' + o.strip().splitlines()[-1] if o.strip() else 'OK')


def elems(cmds, cat=None, **kw):
    q = 'elements ' + json.dumps({'category': cat} if cat else {})
    o, e, c = run(list(cmds) + [q], **kw)[:3]
    if c:
        return e.strip()
    return json.loads(o.strip().splitlines()[-1])['elements']


def saved(cmds, **kw):
    o, e, c, s = run(cmds, save='out.bimcraft', **kw)
    if c:
        return e.strip(), None
    return o, json.loads(s)


if __name__ == '__main__':
    cmds = sys.argv[1:]
    o, e, c = run(cmds)
    print(o, end='')
    print(e, end='')
    print('[exit %d]' % c)

