import sys, json, os, subprocess, tempfile, shutil
sys.path.insert(0, '/tmp/members-agent')
from probe import *

def build(cmds):
    o, e, c, s = run(cmds, save='in.bimcraft')
    if c:
        raise Exception(e)
    return json.loads(s)

def try_file(d, cmd='level {"elevation": 9000}', exe=ORIG, extra=()):
    """write d to a temp dir as in.bimcraft and run the original on it"""
    td = tempfile.mkdtemp(prefix='ed', dir='/tmp/members-agent')
    p = os.path.join(td, 'in.bimcraft')
    if isinstance(d, str):
        open(p, 'w').write(d)
    else:
        open(p, 'w').write(json.dumps(d, indent=2))
    args = [exe, 'run', 'in.bimcraft']
    if cmd:
        args += ['--cmd', cmd]
    args += list(extra)
    r = subprocess.run(args, cwd=td, capture_output=True, timeout=60)
    shutil.rmtree(td)
    return (r.stdout.decode().strip() + ' ' + r.stderr.decode().strip()).strip(), r.returncode

def first(d, cat):
    for k, v in d['elements'].items():
        if v['category'] == cat:
            return k, v

