def main(cases):
    verbose = '-v' in sys.argv
    flt = [a for a in sys.argv[1:] if a != '-v']
    sel = [c for c in cases if not flt or any(f in c['name'] for f in flt)]
    with ThreadPoolExecutor(8) as ex:
        results = list(ex.map(compare, sel))
    bad = 0
    for c, diffs in zip(sel, results):
