#!/usr/bin/env python3
"""Random parameter combinations for every member command, several commands per case."""
import sys, json, random
sys.path.insert(0, '/tmp/members-agent')
from reg import case, main

R = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 and sys.argv[1].isdigit() else 7)
RUNS = ['beam', 'strip_footing', 'pipe', 'duct', 'conduit', 'cable_tray', 'wire', 'down_conductor', 'ground_conductor', 'cabling']
TYPES = {
    'beam': ['Beam 150 x 400', 'Beam 200 x 500', 'Steel Tube 150'], 'strip_footing': ['Strip 600 x 300'],
    'pipe': ['Copper 22', 'PVC 110', 'PVC 25', 'PVC 50'], 'duct': ['Rectangular 400 x 300', 'Rectangular 600 x 400', 'Round 300'],
    'conduit': ['PVC 20', 'PVC 25', 'PVC 32', 'Steel 25'], 'cable_tray': ['Perforated 100 x 50', 'Perforated 200 x 50', 'Perforated 300 x 100'],
    'wire': ['Wire 2.5', 'Wire 4', 'Wire 6'], 'down_conductor': ['Copper 8', 'Flat 25 x 3', 'Steel 8'],
    'ground_conductor': ['Copper 9', 'Steel 8'], 'cabling': ['Cat6', 'Cat6A', 'Optical 3'],
    'column': ['Rectangular 400 x 400', 'Round 300'], 'structural_column': ['Concrete 200 x 500', 'Concrete 300 x 300', 'Concrete Round 400'],
    'footing': ['Footing 1200 x 1200', 'Footing 1500 x 1500'],
}


def num():
    k = R.random()
    if k < 0.3:
        return R.choice([0, 100, 500, 1000, 2500, 3000, -300, -1000, 0.5, 1, 1.5, 2])
    if k < 0.6:
        return round(R.uniform(-5000, 5000), R.choice([0, 1, 2, 3]))
    if k < 0.8:
        return R.uniform(-10000, 10000)
    return R.choice([1e9, -1e9, 1e9 + 1, 123456789.123, -0.0, 1e-9, 7, 0.1, 0.3])


def pt():
    if R.random() < 0.1:
        return R.choice([[0, 0], [1000, 0], [num(), num()], [1], 'x', None, [0, 0, 0]])
    return [R.choice([0, 1000, 2000, 3000, num()]), R.choice([0, 1000, 2000, num()])]


def bad():
    return R.choice([None, 'x', '', True, [], {}, -1, 0, 1e10, 'Level 2', 100001, '100001'])


def run_cmd(c):
    p = {}
    n = R.choice([1, 2, 2, 2, 3, 4])
    pts = [pt() for _ in range(n)]
    if R.random() < 0.15:
        pts = [pts[0], pts[0]]
    p['points'] = pts
    if R.random() < 0.2: p['closed'] = R.choice([True, False, None, 1])
    if R.random() < 0.4: p['type'] = R.choice(TYPES[c] + ['nope', 5, TYPES['column'][0]])
    if R.random() < 0.3: p['level'] = R.choice(['Level 1', 'Level 2', 100000, 100001, '100001', 'nope', None, True])
    if R.random() < 0.6: p['offset'] = num() if R.random() < 0.9 else bad()
    if R.random() < 0.4: p['end_offset'] = num() if R.random() < 0.9 else bad()
    if R.random() < 0.4: p['justify'] = R.choice(['top', 'centre', 'center', 'bottom', 'TOP', 'middle', 5, None])
    if R.random() < 0.3: p['system'] = R.choice(['Cold water', '', 'Circuit 3', 'S' * 257, 7, None])
    if R.random() < 0.05: p[R.choice(['points', 'offset', 'type', 'level'])] = bad()
    return '%s %s' % (c, json.dumps(p))


def col_cmd(c):
    p = {'at': pt()}
    if R.random() < 0.4: p['type'] = R.choice(TYPES[c] + ['nope', 5])
    if R.random() < 0.3: p['level'] = R.choice(['Level 1', 'Level 2', 100000, '100001', 'nope', None])
    if R.random() < 0.3: p['angle'] = R.choice([0, 30, 45, 90, -15.5, 400, num()])
    if c == 'footing':
        if R.random() < 0.5: p['thickness'] = R.choice([400, 500, 0, -1, 1, 1.5, num()])
        if R.random() < 0.5: p['offset'] = num()
    else:
        if R.random() < 0.4: p['height'] = R.choice([2500, 3000, 0, -1, 1, 1.5, num()])
        if R.random() < 0.3: p['top_level'] = R.choice(['Level 1', 'Level 2', 'nope', None, 100001])
        if R.random() < 0.4: p['base_offset'] = R.choice([0, 100, -500, 2999, 3001, num()])
    if R.random() < 0.05: p[R.choice(list(p))] = bad()
    return '%s %s' % (c, json.dumps(p))


cases = []
N = int(sys.argv[2]) if len(sys.argv) > 2 else 300
for i in range(N):
    cmds = []
    if R.random() < 0.2:
        cmds.append('level {"elevation": %s}' % R.choice([6000, -1000, 4500, 3000.5, 1]))
    if R.random() < 0.15:
        cmds.append('phase {"now": "New Construction"}')
    for _ in range(R.choice([1, 2, 3])):
        c = R.choice(RUNS + ['column', 'structural_column', 'footing'] * 2)
        cmds.append(run_cmd(c) if c in RUNS else col_cmd(c))
    cmds.append('elements {}')
    cases.append(case('fuzz %d' % i, *cmds))

if __name__ == '__main__':
    sys.argv = [sys.argv[0]] + [a for a in sys.argv[3:]]
    main(cases)

